import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { certificateUrl, courseUrl, enrol, leave, lessonUrl, routeId, showCourse } from '../../common/api';
import OutlineList from '../components/OutlineList';
import ProgressBar from '../components/ProgressBar';
import { avatar, duration, failed, t } from '../components/util';

/** /courses/:id — the overview: what the course is, who teaches it, its outline and your progress. */
export default class CoursePage extends Page {
  course = null;
  missing = false;
  busy = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
  }
  load() {
    showCourse(routeId(m.route.param('id'))).then(({
      data
    }) => {
      this.course = data;
      app.setTitle(data.title);
      app.history.push('course', data.title);
      m.redraw();
    }, () => {
      this.missing = true;
      m.redraw();
    });
  }
  toggle(join) {
    if (!this.course) return;
    if (!join && !confirm(t('course.leave_confirm'))) return;
    this.busy = true;
    (join ? enrol : leave)(this.course.id).then(({
      data
    }) => {
      this.course = data;
      this.busy = false;
      m.redraw();
    }, e => {
      this.busy = false;
      failed(e);
      m.redraw();
    });
  }
  view() {
    const course = this.course;
    if (!course) {
      return m(PageStructure, {
        className: "SyllabusCoursePage",
        loading: !this.missing
      }, this.missing ? m("p", {
        className: "SyllabusEmpty"
      }, t('course.missing')) : null);
    }
    return m(PageStructure, {
      className: "SyllabusCoursePage",
      hero: () => this.hero(course),
      sidebar: () => this.sidebar(course)
    }, course.descriptionHtml ? m("div", {
      className: "SyllabusProse Post-body"
    }, m.trust(course.descriptionHtml)) : null, m("h3", {
      className: "SyllabusHeading"
    }, t('course.outline')), this.offer(course), course.outline.length ? m(OutlineList, {
      course: course,
      items: course.outline
    }) : m("p", {
      className: "SyllabusEmpty"
    }, t('course.no_lessons')));
  }
  hero(course) {
    return m("header", {
      className: 'Hero SyllabusHero' + (course.coverUrl ? ' SyllabusHero--cover' : '')
    }, course.coverUrl ? m("img", {
      className: "SyllabusHero-cover",
      src: course.coverUrl,
      alt: ""
    }) : null, m("div", {
      className: "container"
    }, m("div", {
      className: "containerNarrow"
    }, m("div", {
      className: "SyllabusHero-crumbs"
    }, m(Link, {
      href: app.route('syllabus.index')
    }, t('catalogue.title')), course.category ? m("span", null, " \xB7 ", course.category.name) : null), m("h1", {
      className: "Hero-title"
    }, course.title), course.summary ? m("div", {
      className: "Hero-subtitle"
    }, course.summary) : null)));
  }

  /**
   * A paid course the member doesn't hold: Kiosk's offer, drawn by Kiosk's own
   * component so every Buy button on the forum is the same. Nothing at all
   * without Kiosk (the course then simply stays locked).
   */
  offer(course) {
    if (course.access !== 'paid' || course.meetsRule || !app.session.user) return null;
    let LockedNotice = null;
    try {
      const mod = window.flarum?.reg?.get('ernestdefoe-kiosk', 'forum/components/LockedNotice');
      LockedNotice = mod?.default || mod;
    } catch {
      LockedNotice = null;
    }
    return LockedNotice ? m(LockedNotice, {
      type: "syllabus-course",
      id: course.id,
      name: course.title
    }) : null;
  }
  sidebar(course) {
    const me = course.me;
    const next = course.nextLesson;
    return m("nav", {
      className: "SyllabusSide"
    }, m("div", {
      className: "SyllabusSide-card"
    }, course.status === 'draft' ? m("p", {
      className: "SyllabusBadge SyllabusBadge--draft"
    }, t('course.draft_notice')) : null, me ? m('[', null, m(ProgressBar, {
      percent: me.completedAt ? 100 : me.percent,
      done: me.done,
      total: course.lessonCount
    }), course.certificateCode ? m(LinkButton, {
      className: "Button Button--primary Button--block",
      icon: "fas fa-award",
      href: certificateUrl(course.certificateCode)
    }, t('course.view_certificate')) : null, next ? m(LinkButton, {
      className: 'Button Button--block' + (course.certificateCode ? '' : ' Button--primary'),
      icon: "fas fa-play",
      href: lessonUrl(course, next)
    }, me.done ? t('course.continue') : t('course.start')) : null) : course.canEnrol ? m(Button, {
      className: "Button Button--primary Button--block",
      icon: "fas fa-right-to-bracket",
      loading: this.busy,
      onclick: () => this.toggle(true)
    }, t('course.enrol')) : !app.session.user ? m(Button, {
      className: "Button Button--primary Button--block",
      onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
    }, t('course.login_to_enrol')) : m("p", {
      className: "SyllabusSide-note"
    }, m(Icon, {
      name: "fas fa-lock"
    }), ' ', course.access === 'paid' ? t('course.paid_only') : course.groups.length ? t('course.groups_only', {
      groups: course.groups.map(g => g.name).join(', ')
    }) : t('course.no_access')), !me && course.previewLessons ? m("p", {
      className: "SyllabusSide-note"
    }, t('course.preview_note', {
      count: course.previewLessons
    })) : null), m("ul", {
      className: "SyllabusFacts SyllabusFacts--stacked"
    }, m("li", null, m(Icon, {
      name: "fas fa-list-ol"
    }), " ", t('course.lessons', {
      count: course.lessonCount
    })), course.difficulty ? m("li", null, m(Icon, {
      name: "fas fa-signal"
    }), " ", t('difficulty.' + course.difficulty)) : null, course.estimatedMinutes ? m("li", null, m(Icon, {
      name: "far fa-clock"
    }), " ", duration(course.estimatedMinutes)) : null, m("li", null, m(Icon, {
      name: "fas fa-user-graduate"
    }), " ", t('course.students', {
      count: course.enrolmentCount
    })), course.sequential ? m("li", null, m(Icon, {
      name: "fas fa-arrow-down-1-9"
    }), " ", t('course.sequential')) : null), course.instructors.length ? m("div", {
      className: "SyllabusSide-instructors"
    }, m("h4", null, t('course.instructors')), course.instructors.map(person => m(Link, {
      className: "SyllabusPerson",
      href: app.route('user', {
        username: person.slug
      })
    }, avatar(person), m("span", null, person.displayName)))) : null, course.canEdit ? m("div", {
      className: "SyllabusSide-actions"
    }, m(LinkButton, {
      className: "Button Button--block",
      icon: "fas fa-pen",
      href: app.route('syllabus.edit', {
        id: course.id + '-' + course.slug
      })
    }, t('course.edit')), m(LinkButton, {
      className: "Button Button--block",
      icon: "fas fa-person-chalkboard",
      href: app.route('syllabus.teach') + '?course=' + course.id
    }, t('teach.title'))) : null, me && !me.completedAt ? m(Button, {
      className: "Button Button--link SyllabusSide-leave",
      loading: this.busy,
      onclick: () => this.toggle(false)
    }, t('course.leave')) : null, m(Link, {
      className: "SyllabusSide-back",
      href: courseUrl(course) === m.route.get() ? app.route('syllabus.index') : courseUrl(course)
    }, m(Icon, {
      name: "fas fa-arrow-left"
    }), " ", t('catalogue.back')));
  }
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/pages/CoursePage', CoursePage);